INSERT INTO dcp_clause_sibling_citations (council, chapter_key, section_ref, sibling_chapter_key, sibling_section_ref,
    sibling_pdf_page, sibling_excerpt, verified_note)
VALUES ($sib$wingecarribee$sib$, $sib$wingecarribee-bowral-town-plan$sib$, $sib$part-c-s2/C2.7.2(c)$sib$, $sib$wingecarribee-mittagong-town-plan$sib$,
    $sib$part-c-s2/C2.7.2(c)$sib$, 189,
    $sib$MITTAGONG TOWN PLAN DCP PART C RESIDENTIAL ZONED LAND SECTION 2 DETACHED DWELLINGS & ASSOCIATED DEVELOPMENT Mittagong Town Plan – Effective 17 June 2015 PART C | Page 185 of 319 (g) Provide adequate building separation between new and existing development for the purposes of privacy, ventilation, fire safety and solar access. (h) Provide space between dwellings to maintain the detached housing character and for individual identity and visual interest. (i) Ensure consistent patterns of built and unbuilt spaces within the streetscape. (j) Offer opportunities for deep soil areas and landscaping. C2.7.2 Specific Controls All applications for residential development shall comply with the following controls: (a) Side setbacks of new development will be generally consistent with those of immediately adjacent existing development. (b) Where the side setbacks of immediately adjacent existing development are inconsistent, Council will assess the proposed setbacks of the new development on merit, taking into consideration potential impacts on: (i) The character of the existing streetscape; (ii) Privacy of the proposed dwellings and existing adjacent dwellings; (iii) Solar access to the proposed dwellings and existing dwellings. (iv) Building Code of Australia issues relating to Fire Safety. (c) In general, subject to site assessment, Council requires the following side setbacks: Lot size Minimum required side setback Less than 900m² 0.9m Between 900m² and 1500m² 1.5m Over 1500m² 2.5m C2.8 Rear Setbacks Rear setbacks provide private open space opportunities for both passive and active recreation. Such spaces also provide contiguous areas of mid block tree canopy and significant areas of deep soil. C2.8.1 Objectives The objectives of providing adequate rear setbacks are to: (a) provide private open space for both active and passive recreation which has good solar access. (b) Ensure sufficient area on the site for mature trees and vegetation.$sib$,
    $sib$Located 2026-09-15 in our R2 copy of the Mittagong Town Plan (as amended 17 Jun 2015) (sha256 510613c46ede): clause C2.7.2 starts on page 189; every number of served control(s) [1141, 1142, 1143] ([Decimal('0.9'), Decimal('1.5'), Decimal('2.5')]) is printed on page 189.$sib$)
ON CONFLICT (council, chapter_key, section_ref, sibling_chapter_key) DO NOTHING;

