INSERT INTO dcp_clause_sibling_citations (council, chapter_key, section_ref, sibling_chapter_key, sibling_section_ref,
    sibling_pdf_page, sibling_excerpt, verified_note)
VALUES ($sib$wingecarribee$sib$, $sib$wingecarribee-bowral-town-plan$sib$, $sib$part-c-s4/C4.4.2(b)$sib$, $sib$wingecarribee-mittagong-town-plan$sib$,
    $sib$part-c-s4/C4.4.2(b)$sib$, 220,
    $sib$MITTAGONG TOWN PLAN DCP PART C RESIDENTIAL ZONED LAND SECTION 4 RESIDENTIAL FLAT BUILDINGS Mittagong Town Plan – Effective 17 June 2015 PART C | Page 216 of 319 C4.4 Private Open Space Useable private open space is an essential requirement for all dwellings, particularly residential flat development. When designing new residential developments, the location, orientation and configuration of private open space should all be considered. Rear and side setback areas, courtyards and balconies are all forms of private open space. Areas within the front setback may also be used as private open space, provided that these areas are carefully designed to ensure adequate privacy without presenting solid high walls to the street. C4.4.1 Objectives The controls described below are intended to achieve the following objectives: (a) Provide useable open space, located to maximise solar access. (b) Allow for both passive and active recreation in private open space areas by providing a combination of hard surface, landscaping and deep soil areas. (c) Ensure ease of movement between living areas of dwellings and private open space. C4.4.2 Development Controls (a) All flats must have a principal private open space area; (b) All ground floor flats must provide a minimum private open space area of 30 m² with a minimum length of 4 metres; (c) All above ground floor flats must provide a minimum private open space area of 15 m² with a minimum length of 3 metres; (d) Private open space must be located to maximise solar access; (e) Private open space must allow for a variety of activities by providing a combination of hard surface, landscaping and deep soil areas. (f) The primary private open space should be located adjacent to, and be immediately accessible from, the primary living area. C4.5 Landscaping and Communal Open Space Applicants are reminded to address the landscaping requirements contained in Section 6 of Part A of this Plan as well as the specific controls below: a) Fifty per cent (50%) of any site developed for a residential flat building shall be landscaped to the satisfaction of Council. Landscaping shall be in accordance with a detailed landscaping plan submitted to Council at the Development Application stage and approved by Council prior to the issue of a Construction Certificate$sib$,
    $sib$Located 2026-09-15 in our R2 copy of the Mittagong Town Plan (as amended 17 Jun 2015) (sha256 510613c46ede): clause C4.4.2 starts on page 220; every number of served control(s) [1165] ([Decimal('30')]) is printed on page 220.$sib$)
ON CONFLICT (council, chapter_key, section_ref, sibling_chapter_key) DO NOTHING;

INSERT INTO dcp_clause_sibling_citations (council, chapter_key, section_ref, sibling_chapter_key, sibling_section_ref,
    sibling_pdf_page, sibling_excerpt, verified_note)
VALUES ($sib$wingecarribee$sib$, $sib$wingecarribee-bowral-town-plan$sib$, $sib$part-c-s4/C4.4.2(b)$sib$, $sib$wingecarribee-moss-vale-town-plan$sib$,
    $sib$part-c-s4/C4.4.2(b)$sib$, 227,
    $sib$MOSS VALE TOWN PLAN DCP PART C RESIDENTIAL ZONED LAND SECTION 4 RESIDENTIAL FLAT BUILDINGS Moss Vale Town Plan – Effective 17 June 2015 PART C | Page 223 of 283 Rear and side setback areas, courtyards and balconies are all forms of private open space. Areas within the front setback may also be used as private open space, provided that these areas are carefully designed to ensure adequate privacy without presenting solid high walls to the street. C4.4.1 Objectives The controls described below are intended to achieve the following objectives: (a) Provide useable open space, located to maximise solar access. (b) Allow for both passive and active recreation in private open space areas by providing a combination of hard surface, landscaping and deep soil areas. (c) Ensure ease of movement between living areas of dwellings and private open space. C4.4.2 Development Controls (a) All flats must have a principal private open space area; (b) All ground floor flats must provide a minimum private open space area of 30 m² with a minimum length of 4 metres; (c) All above ground floor flats must provide a minimum private open space area of 15 m² with a minimum length of 3 metres; (d) Private open space must be located to maximise solar access; (e) Private open space must allow for a variety of activities by providing a combination of hard surface, landscaping and deep soil areas. (f) The primary private open space should be located adjacent to, and be immediately accessible from, the primary living area. C4.5 Landscaping and Communal Open Space Applicants are reminded to address the landscaping requirements contained in Section 6 of Part A of this Plan as well as the specific controls below: a) Fifty per cent (50%) of any site developed for a residential flat building shall be landscaped to the satisfaction of Council. Landscaping shall be in accordance with a detailed landscaping plan submitted to Council at the Development Application stage and approved by Council prior to the issue of a Construction Certificate; b) Landscaped open space shall provide outdoor entertainment areas for resident use; c) In each case where a residential flat building is erected on a site having a frontage to a public road, public place or public open space, Council shall require an appropriate treatment of boundaries to those frontages and the whole of the site which remains undeveloped;$sib$,
    $sib$Located 2026-09-15 in our R2 copy of the Moss Vale Town Plan (as amended 17 Jun 2015) (sha256 8bd923d9eb62): clause C4.4.2 starts on page 227; every number of served control(s) [1165] ([Decimal('30')]) is printed on page 227.$sib$)
ON CONFLICT (council, chapter_key, section_ref, sibling_chapter_key) DO NOTHING;

