INSERT INTO dcp_clause_sibling_citations (council, chapter_key, section_ref, sibling_chapter_key, sibling_section_ref,
    sibling_pdf_page, sibling_excerpt, verified_note)
VALUES ($sib$wingecarribee$sib$, $sib$wingecarribee-bowral-town-plan$sib$, $sib$part-c-s4/C4.6$sib$, $sib$wingecarribee-mittagong-town-plan$sib$,
    $sib$part-c-s4/C4.6$sib$, 221,
    $sib$MITTAGONG TOWN PLAN DCP PART C RESIDENTIAL ZONED LAND SECTION 4 RESIDENTIAL FLAT BUILDINGS Mittagong Town Plan – Effective 17 June 2015 PART C | Page 217 of 319 b) Landscaped open space shall provide outdoor entertainment areas for resident use; c) In each case where a residential flat building is erected on a site having a frontage to a public road, public place or public open space, Council shall require an appropriate treatment of boundaries to those frontages and the whole of the site which remains undeveloped; d) Such treatment may include the planting of trees, shrubs, plants and lawns (the species of which may be specified by Council), the erection of fences, walls and screens, or the exclusion thereof; e) The area of the site between the building line and the street alignment shall be devoid of any structure, concrete area, or hard standing surface other than that which is necessary to gain access to the residential flat building; f) Garbage collection receptacles are to be located to the satisfaction of Council and are to be designed and screened so as to be screened from any public road, public place or public open space; g) A tradesman’s toilet, independent of a sole occupancy unit, will be required where 10 or more units are envisaged on a site. The toilet shall be appropriately screened from any public road, public place or public open space. C4.6 Off-street Parking (a) Off street parking will be provided at the following rates: (b) Dedicated resident parking at a rate of 1 space per 1 and 2 bedroom dwellings (c) Dedicated resident parking at a rate of 2 spaces per 3 or more bedroom dwellings (d) Dedicated visitor parking at a rate of 1 space per 3 dwellings (rounded up to the nearest whole number) (e) Council may require additional visitor parking spaces to be provided in areas where opportunities for on-street visitor parking are deemed to be insufficient. (f) The width of driveways will be limited to 25% of the frontage to a public street but meet the minimum requirements of standard drawings SD107. (g) No parking space, covered or uncovered, shall be provided between the building line and the frontage to the site. At least one parking space per dwelling shall be a covered parking space. (h) Where garages are provided or where any wall abuts a parking space and dimensions of the car parking space shall be greater than otherwise required, a minimum width of 3.6 metres shall apply to any single undercover garage. Adequate clearance and additional impact reinforcement to buildings will apply where undercover car parking is envisaged. (i) In the case of a residential flat building requiring in excess of four car parking spaces with a common access way, sufficient space shall be provided so that no reverse manoeuvre onto a road is required.$sib$,
    $sib$Located 2026-09-15 in our R2 copy of the Mittagong Town Plan (as amended 17 Jun 2015) (sha256 510613c46ede): clause C4.6 starts on page 221; every number of served control(s) [1168, 1169] ([Decimal('1'), Decimal('2')]) is printed on page 221.$sib$)
ON CONFLICT (council, chapter_key, section_ref, sibling_chapter_key) DO NOTHING;

INSERT INTO dcp_clause_sibling_citations (council, chapter_key, section_ref, sibling_chapter_key, sibling_section_ref,
    sibling_pdf_page, sibling_excerpt, verified_note)
VALUES ($sib$wingecarribee$sib$, $sib$wingecarribee-bowral-town-plan$sib$, $sib$part-c-s4/C4.6$sib$, $sib$wingecarribee-moss-vale-town-plan$sib$,
    $sib$part-c-s4/C4.6$sib$, 228,
    $sib$MOSS VALE TOWN PLAN DCP PART C RESIDENTIAL ZONED LAND SECTION 4 RESIDENTIAL FLAT BUILDINGS Moss Vale Town Plan – Effective 17 June 2015 PART C | Page 224 of 283 d) Such treatment may include the planting of trees, shrubs, plants and lawns (the species of which may be specified by Council), the erection of fences, walls and screens, or the exclusion thereof; e) The area of the site between the building line and the street alignment shall be devoid of any structure, concrete area, or hard standing surface other than that which is necessary to gain access to the residential flat building; f) Garbage collection receptacles are to be located to the satisfaction of Council and are to be designed and screened so as to be screened from any public road, public place or public open space; g) A tradesman’s toilet, independent of a sole occupancy unit, will be required where 10 or more units are envisaged on a site. The toilet shall be appropriately screened from any public road, public place or public open space. C4.6 Off-street Parking (a) Off street parking will be provided at the following rates: (b) Dedicated resident parking at a rate of 1 space per 1 and 2 bedroom dwellings (c) Dedicated resident parking at a rate of 2 spaces per 3 or more bedroom dwellings (d) Dedicated visitor parking at a rate of 1 space per 3 dwellings (rounded up to the nearest whole number) (e) Council may require additional visitor parking spaces to be provided in areas where opportunities for on-street visitor parking are deemed to be insufficient. (f) The width of driveways will be limited to 25% of the frontage to a public street but meet the minimum requirements of standard drawings SD107. (g) No parking space, covered or uncovered, shall be provided between the building line and the frontage to the site. At least one parking space per dwelling shall be a covered parking space. (h) Where garages are provided or where any wall abuts a parking space and dimensions of the car parking space shall be greater than otherwise required, a minimum width of 3.6 metres shall apply to any single undercover garage. Adequate clearance and additional impact reinforcement to buildings will apply where undercover car parking is envisaged. (i) In the case of a residential flat building requiring in excess of four car parking spaces with a common access way, sufficient space shall be provided so that no reverse manoeuvre onto a road is required. (j) Except where the Roads and Traffic Authority or Police require otherwise, access driveways and manoeuvring areas shall be the minimum widths and other dimensions as outlined in Council’s relevant technical specifications. (k) Suitable means of physical separation of driveways and parking areas from landscaped open areas shall be provided to prevent indiscriminate vehicular movement upon such areas.$sib$,
    $sib$Located 2026-09-15 in our R2 copy of the Moss Vale Town Plan (as amended 17 Jun 2015) (sha256 8bd923d9eb62): clause C4.6 starts on page 228; every number of served control(s) [1168, 1169] ([Decimal('1'), Decimal('2')]) is printed on page 228.$sib$)
ON CONFLICT (council, chapter_key, section_ref, sibling_chapter_key) DO NOTHING;

-- The sibling plans' own R2 copies, so each sibling citation can link its plan (the Bowral chapter already has one).
UPDATE dcp_chapter_registry
   SET r2_public_pdf_url = 'https://pub-7f3b945f2f0045d6991a6b9d6db51cd8.r2.dev/' || r2_current_path
 WHERE council = 'wingecarribee' AND is_active AND r2_public_pdf_url IS NULL
   AND chapter_key IN ('wingecarribee-mittagong-town-plan', 'wingecarribee-moss-vale-town-plan')
   AND r2_current_path IS NOT NULL;
